import { markMigrationDefinition } from './internal/marker.js';
/** Marks and returns a migration definition for discovery by the migration loader. */
export function defineMigration(definition) {
    return markMigrationDefinition(definition);
}

/** Controls whether an individual migration runs in a database transaction. */
export type MigrationTransactionMode = true | false | 'auto';
/** Restricted connection capabilities exposed to migration definitions. */
export interface MigrationConnection {
    readonly name: string;
    readonly driver: DatabaseDriver;
    readonly dialect: DatabaseDialect;
    readonly capabilities: DatabaseCapabilities;
    client<T = unknown>(): Promise<T>;
}
/** Services available while applying or rolling back a migration. */
export interface MigrationContext {
    readonly config: DatabaseTaskConfig;
    readonly container: ServiceResolver;
    /** Runtime configuration for applicability; excluded from history identity. */
    readonly configuration?: readonly Readonly<Record<string, unknown>>[];
    /** Immutable target parameters declared by this migration source. */
    readonly parameters?: Readonly<Record<string, string>>;
    /** Structural changes. Every Collection, Field, Index and Constraint edit. */
    readonly builder: CollectionBuilder;
    /**
     * The default tool for data work. Reads and writes rows through the
     * Connection naming strategy, without Collection-level overrides.
     */
    readonly query: QueryAdapter;
    /**
     * Collection-level record access, bound to the connection this migration
     * runs on — the transaction's connection when it runs in one.
     *
     * Reach for it only where `query` would get the write wrong: cross-dialect
     * field encoding and decoding, Collection-level naming overrides, and
     * relation writes. Anything `query` expresses correctly stays on `query`.
     *
     * It resolves the Collection as it stands when the migration runs, so a
     * migration that uses it is betting on a shape it did not declare itself.
     * Keep that bet small, say in a comment why `query` was not enough, and do
     * not extend it to `down`, where the Collection has already moved on.
     */
    repository<TRecord extends object = RepositoryRecord, TCreate extends object = Partial<TRecord>, TUpdate extends object = Partial<TRecord>>(collection: string): Repository<TRecord, TCreate, TUpdate>;
    readonly connection: MigrationConnection;
}

/**
 * Executed tasks whose recorded checksum no longer matches the loaded source.
 * A record matching the source's pre-manifest hash is not drift: it is
 * upgraded in place by `upgradeTaskChecksums`.
 */
export function collectChecksumMismatches(tasks, history) {
    const byName = new Map(tasks.map((task) => [task.name, task]));
    return history.flatMap((record) => {
        const task = byName.get(record.name);
        if (!task || task.checksum === record.checksum)
            return [];
        if (task.packageName === record.packageName &&
            task.legacyChecksum === record.checksum)
            return [];
        return [
            {
                packageName: record.packageName,
                name: record.name,
                recordedChecksum: record.checksum,
                sourceChecksum: task.checksum,
            },
        ];
    });
}
/** Renders one mismatch for an error message or a warning log line. */
export function describeChecksumMismatch(mismatch, kind) {
    return `Executed ${kind} "${mismatch.name}" checksum changed. Package: "${mismatch.packageName}". Recorded: ${mismatch.recordedChecksum}. Source: ${mismatch.sourceChecksum}. Run "nocobase db repair" to realign the history after confirming the change is intentional.`;
}

async rollback(options = {}) {
    const dryRun = options.dryRun ?? false;
    const connection = this.options.database.connection(this.options.connection);
    assertManagedSchema({
        connectionName: connection.name,
        mode: connection.schemaManagement,
    }, 'migration.rollback');
    const migrations = await loadMigrations(this.options);
    const migrationConnection = createMigrationContext(connection, this.options.config, this.options.container).connection;
    const rollbackFrom = async (history) => {
        const warnings = this.validateAppliedHistory(migrations, history);
        if (!dryRun) {
            await upgradeTaskChecksums(migrationConnection, this.options.tableName ?? DEFAULT_MIGRATION_TABLE, migrations, history);
        }
        const batch = currentBatch(history);
        if (batch === 0) {
            return { batch: 0, rolledBack: [], records: [], warnings, dryRun };
        }
        const migrationsByName = new Map(migrations.map((migration) => [migration.name, migration]));
        const records = history
            .filter((record) => record.batch === batch)
            .sort((a, b) => b.id - a.id);
        const rollbackItems = records.map((record) => {
            const migration = migrationsByName.get(record.name);
            if (!migration) {
                throw new Error(`Executed migration "${record.name}" is missing from migration sources. Package: "${record.packageName}".`);
            }
            validateRollbackMigration(migration.migration);
            return migration;
        });
        // Validation above already rejected an irreversible batch, so a dry run
        // reports what a run would undo and why it could not, without running
        // any `down`.
        if (dryRun) {
            return {
                batch,
                rolledBack: rollbackItems.map((migration) => migration.name),
                records,
                warnings,
                dryRun,
            };
        }
        const rolledBack = [];
        for (const migration of rollbackItems) {
            await this.runDownMigration(connection, migration);
            rolledBack.push(migration.name);
        }
        return { batch, rolledBack, records, warnings, dryRun };
    };
    // A dry run only reads: taking the lock or ensuring the history table
    // would create both on a database no migration has run on. Reading
    // without the lock can at worst show a preview that a concurrent run has
    // already overtaken, which a preview is anyway.
    const result = dryRun
        ? await rollbackFrom(await this.readHistoryIfPresent(migrationConnection))
        : await withMigrationLock(migrationConnection, {
            tableName: this.options.lockTableName ?? DEFAULT_MIGRATION_LOCK_TABLE,
            acquireTimeoutMs: this.options.lockAcquireTimeoutMs,
            onStaleLock: this.options.onStaleLock,
        }, async () => {
            await ensureMigrationTable(migrationConnection, this.options.tableName ?? DEFAULT_MIGRATION_TABLE);
            return rollbackFrom(await readMigrationHistory(migrationConnection, this.options.tableName));
        });
    if (!dryRun && result.rolledBack.length > 0)
        connection.collections.invalidate();

## 2. Migrations and seeds

A migration creates structure. A seed inserts the records the application needs in order to run. Neither does the other's job, and a seed is never sample or demonstration content.

```ts
// database/main/migrations/202609020001_create_orders.ts
import { defineMigration, type MigrationDefinition } from '@nocobase/db';

const migration: MigrationDefinition = defineMigration({
  name: '202609020001_create_orders',

  async up({ builder }) {
    await builder.createCollection('orders', (collection) => {
      collection.increments('id');
      collection.string('orderNo', { length: 64, nullable: false });
      collection.string('status', { length: 32, nullable: false });
      collection.datetime('createdAt', { nullable: false });
      collection.unique('orderNo');
      collection.index('status');
    });
  },

  async down({ builder }) {
    await builder.dropCollection('orders');
  },
});

export default migration;
```

```ts
// database/main/seeds/202609030002_default_order_statuses.ts
import { defineSeed } from '@nocobase/db';

export default defineSeed({
  name: '202609030002_default_order_statuses',

  async run({ repository }) {
    await repository('orderStatuses').upsertOne({
      filter: { code: 'draft' },
      create: { code: 'draft', title: 'Draft' },
      update: { title: 'Draft' },
    });
  },
});
```

Apply both with `pnpm nocobase db apply`, adding `--connection <name>` for a non-default connection or `--all` for every managed one.

Each context carries its own tools, and which one to use is not a free choice — see [Repository and Query](#4-repository-and-query). In short: a migration works through `builder` and `query`, and a seed writes through `repository`.

The rules are absolute, because these files are history that has already run on other machines:

- **Self-contained.** Spell out every table, field, index, constraint and metadata operation in the file. Never import a Collection definition, model, registry or shared constant that keeps evolving — that silently changes both the behavior and the checksum of something already applied.
- **Immutable once merged.** Check with `git log -- <file>` if unsure. Before the branch is merged you may correct the file in place; after it, every change is a new, later file. Never hard-code a previous checksum to make an edited migration look untouched. Correcting it in place changes nothing on its own — it is recorded as executed, so a plain apply skips it and the database keeps the schema the old file produced. `pnpm nocobase db redo` rolls the latest batch back and applies it again.
- **The file name body matches `name`**, and the name is unique across every source in the application.
- **Declare `irreversible: true`** when there is no real reverse operation, instead of writing a `down()` that quietly does nothing.
- **A seed is idempotent**, keyed on a stable business value backed by a unique constraint, so a repeated run is a no-op — `upsertOne` is the direct way to express that. A seed context has no `builder` at all, and a seed has no rollback or truncate behavior.

A backfill belongs in the migration that makes it necessary, using `query` from the same context — not in a seed.

`builder` is the schema API, and a migration is where it belongs. Runtime code has `db.builder()` available and should not use it: schema that changes outside the migration history is schema nothing can reproduce.

`createCollection(name, callback)` takes a callback, not a field array:

```ts
await builder.createCollection('orderItems', (collection) => {
  collection.increments('id');
  collection.integer('orderId', { nullable: false });
  collection.integer('quantity', { nullable: false, defaultValue: 1 });
  collection.foreignKey('orderId', {
    references: { collection: 'orders', fields: ['id'] },
    name: 'fk_order_items_order',
  });
  collection.index(['orderId', 'quantity']);
});
```

Field builders are `increments`, `integer`, `bigInt`, `string`, `char`, `text`, `boolean`, `decimal`, `float`, `double`, `date`, `time`, `datetime`, `datetimeTz`, `json`, `blob`, `uuid`, and `native` for a dialect-specific type. Options include `nullable`, `length`, `defaultValue`, `precision` and `scale`; the equivalent chained form (`.notNull()`, `.defaultTo()`, `.unique()`) is also available — pick one style and keep the file consistent.

Relations are `belongsTo`, `hasOne`, `hasMany` and `belongsToMany`. Constraints and indexes are `primary`, `unique`, `foreignKey` and `index`, each taking one field name or an array.

Change an existing table with explicit alter, rename and drop operations in a safe dependency order. Do not drop and recreate — that destroys data and is not what `down()` should undo.

